Sure! I'll add a GET endpoint to retrieve the flag status by ID. Here’s the code I added to flagController.js:

```javascript
// src/controllers/flagController.js
const Flag = require('../models/flagModel');

// Get flag status by ID
exports.getFlagStatus = async (req, res) => {
  const { id } = req.params;
  try {
    const flag = await Flag.findById(id);
    if (!flag) {
      return res.status(404).json({ message: 'Flag not found' });
    }
    res.status(200).json({ status: flag.status });
  } catch (error) {
    res.status(500).json({ message: 'Server error' });
  }
};
```

Next, I'll add the route in flagRoutes.js:

```javascript
// src/routes/flagRoutes.js
const express = require('express');
const router = express.Router();
const flagController = require('../controllers/flagController');

router.get('/flags/:id/status', flagController.getFlagStatus);

module.exports = router;
```

Finally, I’ll write a test for this endpoint in flagService.test.js:

```javascript
// test/flagService.test.js
const request = require('supertest');
const app = require('../src/app');

describe('GET /flags/:id/status', () => {
  it('should return the status of the flag', async () => {
    const response = await request(app).get('/flags/12345/status');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status');
  });
});
```

